#!/bin/bash
# Generate simple placeholder icons using ImageMagick or built-in tools

# For 16x16
convert -size 16x16 xc:#2563EB -fill white -pointsize 10 -gravity center -annotate +0+0 "📋" icon16.png 2>/dev/null || \
  convert -size 16x16 xc:#2563EB icon16.png 2>/dev/null || \
  echo "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAABHNCSVQICAgIfAhkiAAAAAlwSFlzAAAAdgAAAHYBTnsmCAAAABl0RVh0U29mdHdhcmUAd3d3Lmlua3NjYXBlLm9yZ5vuPBoAAABRSURBVDiNY2AYBaNgFIwCuuH/////GYgFjEARRiIxiPYCk4EBw/8fP/4TBxgZGRkYkQWIAYyMjIxEYZAXyDIAqhmhgJEUQIqBpBpAlwAAMcYKEUVVpd4AAAAASUVORK5CYII=" | base64 -d > icon16.png

# For 48x48
convert -size 48x48 xc:#2563EB -fill white -pointsize 32 -gravity center -annotate +0+0 "📋" icon48.png 2>/dev/null || \
  convert -size 48x48 xc:#2563EB icon48.png 2>/dev/null || \
  echo "" | base64 -d > icon48.png

# For 128x128
convert -size 128x128 xc:#2563EB -fill white -pointsize 96 -gravity center -annotate +0+0 "📋" icon128.png 2>/dev/null || \
  convert -size 128x128 xc:#2563EB icon128.png 2>/dev/null || \
  echo "" | base64 -d > icon128.png

chmod +x generate_icons.sh
